uint hh_(uint x){x^=x>>16;x*=0x7feb352du;x^=x>>15;x*=0x846ca68bu;x^=x>>16;return x;}float hash(vec2 p){uvec2 q=floatBitsToUint(p+vec2(0.));// +0. folds -0.0 into 0.0
